#define MOTIF_MAX 32

__attribute__((visibility("default")))
long __cdecl recherche_octets_pure(
    const unsigned char* fenetre,
    long taille_fenetre,
    const unsigned char* motif,
    long taille_motif,
    long depart
)
{
    // E1 : le motif vide (P4 = 0) → verdict -5 ENTRÉE
    if (taille_motif == 0) {
        return -5;
    }
    // E2 : le motif > 32 (P4) → verdict -5 ENTRÉE
    if (taille_motif > MOTIF_MAX) {
        return -5;
    }
    // E3 : le départ hors fenêtre (P5 > rdx) → verdict -5 ENTRÉE
    if (depart > taille_fenetre) {
        return -5;
    }

    // Q2 & Q3 : le motif plus long que la plage restante → -1 IMMÉDIAT
    //            le départ = rdx (la plage vide) → -1
    long plage_restante = taille_fenetre - depart;
    if (plage_restante <= 0 || taille_motif > plage_restante) {
        return -1;
    }

    const unsigned char* fin_plage = fenetre + taille_fenetre - taille_motif;
    const unsigned char* p_depart = fenetre + depart;

    // Recherche de la première occurrence
    for (const unsigned char* p_candidat = p_depart; p_candidat <= fin_plage; ++p_candidat) {
        // I2 : LA COMPARAISON PAR LA CARTE : libc-02 (memcmp)
        if (memcmp(p_candidat, motif, taille_motif) == 0) {
            // Q1 : position ABSOLUE de la PREMIÈRE occurrence
            return p_candidat - fenetre;
        }
    }

    // Si aucune occurrence n'est trouvée
    return -1;
}
