    __int64 session_handle,
    __int64 plan_base,
    __int64 nibble,
    __int64 cursor,
    __int64 view_offset,
    __int64 fill_size,
    __int64* refus_quitter,
    __int64* cadre_sale,
    __int64* tampon_vision,
    __int64* nibble_attente
) {
