            __int64 journal_base = plan_base + JOURNAL_OFFSET;
            __int64 journal_count = *(volatile __int64*)(journal_base + JOURNAL_COUNT_OFFSET);
            __int64 journal_octet = *(volatile __int64*)(journal_base + JOURNAL_OCTET_OFFSET);

            if (journal_count >= JOURNAL_ENTRIES) {
                rax = -3;
                return rax;
            }

            if (cursor < fill_size) {
                __int64 octet = (*nibble_attente << 4) | nibble;
                *(volatile unsigned char*)(tampon_vision + cursor - view_offset) = octet;

                __int64 entry_offset = journal_octet * JOURNAL_ENTRY_SIZE;
                *(volatile unsigned long long*)(journal_base + entry_offset) = cursor;
                *(volatile unsigned char*)(journal_base + entry_offset + 8) = octet;
                journal_octet++;
                if (journal_octet >= JOURNAL_ENTRIES) journal_octet = 0;
                *(volatile __int64*)(journal_base + JOURNAL_OCTET_OFFSET) = journal_octet;
                if (journal_count < JOURNAL_ENTRIES) journal_count++;
                *(volatile __int64*)(journal_base + JOURNAL_COUNT_OFFSET) = journal_count;
            } else {
                rax = -3;
                return rax;
            }

            *refus_quitter = 0;
            *cadre_sale = 1;
            cursor++;
            if (cursor >= fill_size) cursor = fill_size - 1;
